const rows = $input.all().map(r => r.json);
const program_id = $('Webhook').first().json.body.program_id;

let sprs = 110;
let ssp_done = true;

for (const r of rows) {
  if (!r.is_applicable) continue;
  if (r.nist_id === '3.12.4' && r.status !== 'fully_implemented') {
    ssp_done = false;
  }
  if (r.status !== 'fully_implemented' && r.dod_score_value) {
    sprs -= Number(r.dod_score_value);
  }
}

if (!ssp_done) {
  sprs = -203;
}

// FAR & Above cumulative score by phase
// Phase scores represent controls completed per phase
const phaseScores = { 1: 37, 2: 32, 3: 34, 4: 37, 5: 47 };
let far_above_score = 0;

for (let p = 1; p <= 5; p++) {
  const phaseRows = rows.filter(r => String(r.far_above_phase) === String(p) && r.is_applicable);
  if (!phaseRows.length) continue;
  const allDone = phaseRows.every(r => r.status === 'fully_implemented');
  if (allDone) {
    far_above_score += phaseScores[p];
  } else {
    break;
  }
}

return [{
  json: {
    sprs_score: Math.max(-203, Math.min(110, sprs)),
    far_above_score,
    program_id
  }
}];

